INSERT INTO feature VALUES('boot-core','runtime','The operations on bytes that allocate nothing','bootstrap','partial','ordinary',NULL,'The crate `gandr-boot-core` copies, moves, fills and compares ranges of bytes, finds a byte or a range in a range, checks a range as UTF-8 and finds the zero byte that ends a C string. Each function takes each range as an address and a length, so the direct call of Rust can name it, and an empty range can have any address. A move takes ranges that share bytes. A copy or a move into a place that is too short gets a refusal, and no byte changes. A search gives the first position or an absence, and the check of UTF-8 gives the position of the first fault. No function allocates or panics, and the crate is `no_std`. One copy of 4096 bytes takes 43 ns on Linux x86-64, 45 ns on macOS arm64 and 515 ns on Linux riscv64 at the median. No corpus source calls the crate yet, because the direct call of Rust is still open (#7840), and no twin in gandr replaces the crate yet (#7833).','boot-core','crates/boot-core/tests/block.rs crates/boot-core/tests/search.rs crates/boot-core/tests/check.rs','crate-tests','#7833 #7840');
